def valid(number):
    """Return True if the card number passes the Luhn check."""
    if not isinstance(number, str):
        return False

    digits = number.replace(" ", "")

    if len(digits) < 2:
        return False
    if not all("0" <= char <= "9" for char in digits):
        return False

    total = 0
    for index, char in enumerate(reversed(digits)):
        digit = int(char)
        if index % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    return total % 10 == 0
